export const getFeatureById = (id) => DEFAULT_FEATURES.find(f => f.id === id);

export const getFeaturesByCategory = (category) => 
  DEFAULT_FEATURES.filter(f => (f.category || '').toLowerCase() === (category || '').toLowerCase());
